 parts=['<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FLOW — Audit du comptage et de Process Management</title><style>body{font:16px/1.6 system-ui,sans-serif;color:#182632;background:#faf8f4;margin:0}main{max-width:1160px;margin:auto;padding:28px}section{padding:24px;background:white;margin:20px 0;border-radius:12px}header{padding:28px;background:#236159;color:white;border-radius:12px}table{width:100%;border-collapse:collapse;font-size:14px}th,td{padding:10px;border:1px solid #d0ded9;text-align:left;vertical-align:top}th{background:#e5f3ed}.scroll{overflow:auto}a{color:#236159}li{margin:8px 0}.notice{border-left:5px solid #b65d16;padding:14px;background:#fff0da}code{overflow-wrap:anywhere}@media(max-width:650px){main{padding:12px}section{padding:14px}}</style><main><header><p>Étude économique FLOW · 30 octobre 2026</p><h1>Comptage COCOMO et réserve sur Process Management</h1><p>Audit à estimations retenues inchangées. Composants OSS ajoutés comme propositions documentées.</p></header>']
 parts+=['<section><h2>Résultat principal</h2><p><strong>COCOMO II attend des instructions logiques, pas des lignes physiques.</strong> Remplacer le compteur actuel par le profil USC sur les instructions programme mesurées produit environ <strong>4 130 JH</strong> au lieu de 4 160 après les mêmes arrondis. Avant arrondis : variation de −41 JH, soit −0,99 %. Ce résultat est une sensibilité, pas une adoption ni une preuve de précision.</p><p class="notice"><strong>Le faible écart de comptage ne valide pas les 340 JH de Process Management.</strong> L’audit relève un éditeur métier non dimensionné, des interfaces de tâches/formulaires insuffisamment comparées, et un analogue de requêtes CRM insuffisant pour le Process Mining et les analytics. Aucun nouveau total n’est inventé.</p></section>']
 rows=[]
